class Solution {
    public int monotoneIncreasingDigits(int n) {
        char[] s = Integer.toString(n).toCharArray();
        int i = 1, d = s.length;
        while (i < d && s[i-1] <= s[i]) i++;
        if (i == d) return n;
        while (i > 0 && s[i-1] == s[i]) i--;
        s[i]--;
        for (int j = i + 1; j < d; j++) s[j] = '9';
        return Integer.parseInt(new String(s));
    }
}

